foreach($edition in @('qt','classic')){
 $stage=if($edition -eq 'qt'){"$repo/_bin/aac-sdk184-qt-win-stage"}else{"$repo/_bin/aac-sdk184-classic-fixed-stage"}
 $exe=if($edition -eq 'qt'){'FoxicMPq.exe'}else{'FoxicMP64.exe'};$audio=if($edition -eq 'qt'){'wasapi'}else{'null'}
 $env:PATH="$repo/_bin/aac-sdk184-fixture-tools;$stage;$env:SystemRoot/System32;$env:SystemRoot";$env:QT_QPA_PLATFORM_PLUGIN_PATH="$stage/platforms";$env:QT_QPA_PLATFORM='offscreen'
 $name="aac-expiry-windows-$edition"
 $arguments=@('-B',"$repo/tests/progressive_aac_package_test.py",'--edition',$edition,'--scenario','aac-heartbeat','--player',"$stage/$exe",'--sdk-directory',"$stage/integration",'--reader-runner',"$repo/_bin/continuous-aac-qt-windows/foxicmp-progressive-reader-tests.exe",'--expected-audio-output',$audio,'--report-directory',"$repo/_bin/$name-results")
 $process=Start-Process -FilePath $py -ArgumentList $arguments -WindowStyle Hidden -PassThru -RedirectStandardOutput "$repo/_bin/$name.log" -RedirectStandardError "$repo/_bin/$name.stderr.log"
