"""Private observer; preserves the strict primary result, never edits a player."""
import ctypes,importlib,importlib.util,json,os,sys,time,traceback
from pathlib import Path
from ctypes import wintypes as w
root=Path(__file__).resolve().parents[1];sys.dont_write_bytecode=True;os.environ['PYTHONDONTWRITEBYTECODE']='1'
sdk=root/'_bin/aac-sdk184-classic-fixed-stage/integration'
sys.path[:0]=[str(sdk),str(root/'tests')]
for name in ('progressive_schema','progressive_client','progressive_integrity','progressive_resources','progressive_sdk','progressive_v2','progressive_continuous','progressive_windows','progressive_preview','progressive_writer'):
 module=importlib.import_module(name);assert Path(module.__file__).resolve().parent==sdk
import progressive_continuous_aac_heartbeat_stress as stress
import progressive_aac_package_test as driver
report=root/'_bin/aac-expiry-pool-diagnostic-results';report.mkdir(exist_ok=False)
k=ctypes.WinDLL('kernel32',use_last_error=True);nt=ctypes.WinDLL('ntdll')
k.CreateToolhelp32Snapshot.argtypes=[w.DWORD,w.DWORD];k.CreateToolhelp32Snapshot.restype=w.HANDLE;k.CloseHandle.argtypes=[w.HANDLE]
k.OpenThread.argtypes=[w.DWORD,w.BOOL,w.DWORD];k.OpenThread.restype=w.HANDLE
nt.NtQueryInformationThread.argtypes=[w.HANDLE,w.ULONG,ctypes.c_void_p,w.ULONG,ctypes.c_void_p];nt.NtQueryInformationThread.restype=ctypes.c_long
class Thread(ctypes.Structure):
 _fields_=[('dwSize',w.DWORD),('cntUsage',w.DWORD),('threadID',w.DWORD),('ownerPID',w.DWORD),('basePriority',w.LONG),('deltaPriority',w.LONG),('flags',w.DWORD)]
class Module(ctypes.Structure):
 _fields_=[('dwSize',w.DWORD),('moduleID',w.DWORD),('pid',w.DWORD),('globalCount',w.DWORD),('processCount',w.DWORD),('base',ctypes.c_void_p),('size',w.DWORD),('module',w.HMODULE),('name',w.WCHAR*256),('path',w.WCHAR*260)]
for name,kind in (('Thread32First',Thread),('Thread32Next',Thread),('Module32FirstW',Module),('Module32NextW',Module)):
 fn=getattr(k,name);fn.argtypes=[w.HANDLE,ctypes.POINTER(kind)];fn.restype=w.BOOL

def entries(flags,pid,kind,first,next):
 handle=k.CreateToolhelp32Snapshot(flags,pid)
 if handle==ctypes.c_void_p(-1).value:raise ctypes.WinError(ctypes.get_last_error())
 try:
  item=kind();item.dwSize=ctypes.sizeof(item);okay=getattr(k,first)(handle,ctypes.byref(item))
  while okay:
   yield item
   okay=getattr(k,next)(handle,ctypes.byref(item))
 finally:k.CloseHandle(handle)

def inventory(pid):
 modules=[dict(name=m.name,path=m.path,base=int(m.base),size=m.size) for m in entries(8|16,pid,Module,'Module32FirstW','Module32NextW')]
 rows=[]
 for t in entries(4,0,Thread,'Thread32First','Thread32Next'):
  if t.ownerPID!=pid:continue
  handle=k.OpenThread(0x40,False,t.threadID)
  if not handle:rows.append(dict(tid=t.threadID,queryError=ctypes.get_last_error()));continue
  try:
   address=ctypes.c_void_p();status=nt.NtQueryInformationThread(handle,9,ctypes.byref(address),ctypes.sizeof(address),None)
   row=dict(tid=t.threadID,status=status,start=hex(address.value or 0))
   if status>=0:
    module=next((m for m in modules if m['base']<=(address.value or 0)<m['base']+m['size']),None)
    if module:row.update(module=module['name'],offset=hex(address.value-module['base']))
   rows.append(row)
  finally:k.CloseHandle(handle)
 return dict(pid=pid,threads=rows,modules=modules)

observations=[];original_sample=stress.sample;original_exercise=stress.exercise;began=time.monotonic()
def observed_sample(pid):
 result=original_sample(pid)
 try:observations.append(dict(seconds=time.monotonic()-began,metrics=result,inventory=inventory(pid)))
 except Exception:observations.append(dict(pid=pid,error=traceback.format_exc()))
 (report/'thread-observations.json').write_text(json.dumps(observations,indent=2)+'\n')
 return result
stress.sample=observed_sample

spec=importlib.util.spec_from_file_location('private_fixed_helper',root/'_bin/aac-expiry-helper-fixed.py');fixed=importlib.util.module_from_spec(spec);spec.loader.exec_module(fixed)
def observed(peers,work,output,mode):
 results=[];baseline=None;violations=[]
 try:
  for index in range(7):
   directory=work/('expiry-%02d'%index);directory.mkdir();destination=output/('expiry-%02d'%index);destination.mkdir()
   result=fixed.exercise(peers,directory,destination,profiles=('paused',),completed=False,media_mode=mode)
   metrics=[observed_sample(p.process.pid) for p in peers]
   if index==0:baseline=metrics
   else:
    for peer,(a,b) in enumerate(zip(baseline,metrics)):
     for key,growth in (('threads',2),('handles',8)):
      if b[key]>a[key]+growth:violations.append(dict(attempt=index,peer=peer,metric=key,baseline=a[key],current=b[key],growth=growth))
   results.append(dict(attempt=index,result=result,metrics=metrics))
   (report/'observations.json').write_text(json.dumps(dict(baseline=baseline,rows=results,violations=violations,acceptance=False),indent=2)+'\n')
   print(json.dumps(dict(attempt=index,helperResult=result['result'],violations=len(violations))),flush=True)
  return dict(result='OBSERVATION',count=7,rows=results,budgetViolations=violations,acceptance=False,privateFixedHelperSha256=stress.sha(fixed.__file__))
 finally:
  rows=[];started=time.monotonic()
  for index in range(13):
   if index:time.sleep(5)
   rows.append(dict(seconds=time.monotonic()-started,players=[dict(metrics=original_sample(p.process.pid),inventory=inventory(p.process.pid)) for p in peers]))
   (report/'idle-after-result.json').write_text(json.dumps(rows,indent=2)+'\n')
stress.exercise=observed
sys.argv=[str(root/'tests/progressive_aac_package_test.py'),'--edition','classic','--scenario','aac-heartbeat','--player',str(root/'_bin/aac-sdk184-classic-fixed-stage/FoxicMP64.exe'),'--sdk-directory',str(sdk),'--reader-runner',str(root/'_bin/continuous-aac-qt-windows/foxicmp-progressive-reader-tests.exe'),'--report-directory',str(report)]
driver.main()
